DRAW = {
    'Eyes': draw_Eyes,
    'Face': draw_Eyes,
    'Fur': draw_Fur,
    'Hair': draw_Hair,
    'Standard': draw_Eyes,
}


def draw(kit, layout, material, p):
    function = DRAW.get(material.get('ruri_uber_part', ''))
    if function is None:
        kit.notice(layout, 'No panel layout for part ' + repr(material.get('ruri_uber_part', '')))
        return
    function(kit, layout, material, p)
